do $check$ begin
if exists(select 1 from task03b_registry r left join public.exam_subjects s on s.id=r.exam_subject_id left join public.exams e on e.content_item_id=r.content_item_id left join public.content_items c on c.id=e.content_item_id left join public.subjects subj on subj.id=s.subject_id where s.id is null or not s.is_active or not c.is_active or e.grade_level is distinct from 3 or (e.academic_year,e.exam_month,e.exam_type) is distinct from (r.academic_year,r.exam_month,r.exam_type) or (s.content_item_id,s.subject_id,s.raw_subject_label,subj.code) is distinct from (r.content_item_id,r.subject_id,r.subject_label,r.subject_code)) then raise exception 'TASK03B_REGISTRY_DRIFT'; end if;
if exists(select 1 from public.answer_key_versions r join task03b_keys s on r.id=s.id where r.id is distinct from s.id or r.content_item_id is distinct from s.content_item_id or r.exam_subject_id is distinct from s.exam_subject_id or r.paper_variant is distinct from s.paper_variant or r.version is distinct from s.version or r.question_count is distinct from s.question_count or r.max_score is distinct from s.max_score or r.source_name is distinct from s.source_name or r.source_url is distinct from s.source_url or r.source_digest is distinct from s.source_digest or r.points_source_name is distinct from s.points_source_name or r.points_source_url is distinct from s.points_source_url or r.points_source_digest is distinct from s.points_source_digest or r.fetched_at is distinct from s.fetched_at or r.verified_at is distinct from s.verified_at or r.corrected_at is distinct from s.corrected_at or r.correction_note is distinct from s.correction_note or r.scoring_version is distinct from s.scoring_version or r.verification_status is distinct from s.verification_status) then raise exception 'TASK03B_DATA_CONFLICT_keys'; end if;
if exists(select 1 from public.exam_questions r join task03b_questions s on r.answer_key_version_id=s.answer_key_version_id and r.question_number=s.question_number where r.answer_key_version_id is distinct from s.answer_key_version_id or r.question_number is distinct from s.question_number or r.answer_type is distinct from s.answer_type or r.correct_answer is distinct from s.correct_answer or r.points is distinct from s.points or r.accepted_answers is distinct from s.accepted_answers or r.all_credit is distinct from s.all_credit or r.question_id is distinct from s.question_id or r.unit is distinct from s.unit or r.domain is distinct from s.domain or r.item_type is distinct from s.item_type) then raise exception 'TASK03B_DATA_CONFLICT_questions'; end if;
if exists(select 1 from public.grade_cutoff_references r join task03b_refs s on r.id=s.id where r.id is distinct from s.id or r.content_item_id is distinct from s.content_item_id or r.exam_subject_id is distinct from s.exam_subject_id or r.elective_key is distinct from s.elective_key or r.elective_label is distinct from s.elective_label or r.grade is distinct from s.grade or r.revision is distinct from s.revision or r.raw_score is distinct from s.raw_score or r.raw_score_min is distinct from s.raw_score_min or r.raw_score_max is distinct from s.raw_score_max or r.standard_score is distinct from s.standard_score or r.percentile is distinct from s.percentile or r.assessment_method is distinct from s.assessment_method or r.raw_certainty is distinct from s.raw_certainty or r.standard_certainty is distinct from s.standard_certainty or r.source_url is distinct from s.source_url or r.raw_source_url is distinct from s.raw_source_url or r.standard_source_url is distinct from s.standard_source_url or r.source_digest is distinct from s.source_digest or r.source_name is distinct from s.source_name or r.fetched_at is distinct from s.fetched_at or r.verified_at is distinct from s.verified_at or r.correction_note is distinct from s.correction_note) then raise exception 'TASK03B_DATA_CONFLICT_refs'; end if;
if exists(select 1 from public.answer_key_versions r join task03b_keys s using(exam_subject_id,paper_variant) where r.id<>s.id) then raise exception 'TASK03B_KEY_FAMILY_CONFLICT'; end if;
if exists(select 1 from public.grade_cutoff_references r join task03b_refs s using(content_item_id,exam_subject_id,elective_key,grade) where r.id<>s.id) then raise exception 'TASK03B_CUTOFF_FAMILY_CONFLICT'; end if;
end $check$;
